function [harmonicmodefile] = MechMonics%  program MechMonics()%%  Compiled by Paul Dawson from codes and scripts from MAE courses, OdfPF, %   pre- and post-processing tools for FEpX, other research projects%   in the Deformation Processes Lab at Cornell University.%%  Driver program for evaluation of discrete harmonic modes for a polycrsytal %    Intent:   solve the negative laplacian equation on each grain using%       files generated by Neper (especially from HEDM data)%%    Input:   (1) nummodes  -- integer number of modes%             (2) nepermeshname -- string with the name of the Neper-generated finite element mesh%             (3) mechmonicsvtkname -- string with the name of the VTK file%                                       with mode and mode gradient fields%%     Output: (1) specified number of discrete harmonic modes (save in grain mesh file)%             (2) gradient fields of each mode%             (3) vtk file for visualization%%          status = ' Starting simulation:  Read files with input data.'neperversionnumber=4;nepermeshname = input('Base name (with extension .msh) of the combined mesh  and microstructure file: ', 's');[meshfile,microstructurefile] = ReadNeperMshFile(nepermeshname);phases = microstructurefile.phases;grains = microstructurefile.grains;ngrains=max(grains);numberofmodes = input('Enter the number of modes to be computed: ', 's');nummodes = str2num(numberofmodes);eigsorsvds = 0;%% Set mesh size variables from mesh coordinate and connectivity arrays%[m n]   = size(meshfile.crd);numnp = n;[m n]   = size(meshfile.con);numel = n;np = meshfile.con';coords = meshfile.crd;%%define local variables for coordinates%x = coords(1,:)';y = coords(2,:)';z = coords(3,:)';%%  set up reference array that gives phase of each grain%phaseofgrain=zeros(1,ngrains);for iele=1:numel phasenum = phases(iele); igrain = grains(iele); phaseofgrain(igrain) = phasenum;end grain_centroids = zeros(3,ngrains); grain_volumes = zeros(1,ngrains); sample_volume = 0;%% Set up the finite element shape function arrays and store in structure%shafac_structure = ShapeFunctionArrays();sfac = shafac_structure.sfac;dndxi = shafac_structure.dndxi;dndet = shafac_structure.dndet;dndze = shafac_structure.dndze;nqptv = shafac_structure.nqpt;wtqp = shafac_structure.wtqp;nnpe = shafac_structure.nnpe;nphases = max(phases);status = ' Reformating mesh without intergrain continuity (no grains share nodal points)'[newnumnp,newnp,newnpinv,newcoords,old2new,grn4np,nepergrn4np,meshfilegbg]=GrainByGrainMesh_Modes(nepermeshname,numel,numnp,np,nnpe,coords,grains);meshfilegbg.ngrains=ngrains;grainbygrainmeshfilename =  [nepermeshname '_' 'meshfile_gbg'];save(grainbygrainmeshfilename,'meshfilegbg')US_Global = zeros(newnumnp,nummodes);DS_Global = zeros(ngrains,nummodes);grad_US_Global = zeros(3*newnumnp,nummodes);m_sqrt_U_Global = zeros(ngrains,3,3);m_sqrt_S_Global = zeros(ngrains,3,3);completed_grains = zeros(ngrains,1);for igrn = 1:1:ngrains    igrnstr = string(igrn);   message = [' Working on Grain Number: ' igrnstr];disp(message)    grainmeshfilename =  [nepermeshname '_' 'meshfile_grn_' num2str(igrn) ];   load(grainmeshfilename);% Set mesh size variables from mesh coordinate and connectivity arrays[m n]   = size(meshfile1X.crd);numnp = n;[m n]   = size(meshfile1X.con);numel = n;np = meshfile1X.con';coords = meshfile1X.crd;%%define local variables for coordinates%    x = coords(1,:)';y = coords(2,:)';z = coords(3,:)';element_volumes = zeros(1,numel);element_centroids = zeros(3,numel); DS = zeros(nummodes,nummodes);US = zeros(numnp,nummodes);if(numnp<nummodes)   status = ' Number of modes exceeds number of nodes; grain will be skipped. 'completed_grains(igrn)=-1;grnstatus = -1;endif(numnp>=nummodes)Fsr=zeros(numel*nnpe,1); Fsv=zeros(numel*nnpe,1); Ksr=zeros(numel*nnpe*nnpe,1); Ksc=zeros(numel*nnpe*nnpe,1); Ksv=zeros(numel*nnpe*nnpe,1);Jsr=zeros(numel*nnpe*nnpe,1); Jsc=zeros(numel*nnpe*nnpe,1); Jsv=zeros(numel*nnpe*nnpe,1);fc=1; kc=1;jc=1;kmatrix = [ 1 0 0 ; 0 1 0; 0 0 1]; fe= zeros(nnpe,1);%for   iele =1:1:numel        [dndx,dndy,dndz,detj,elvolume] = SFDerivatives(iele,nnpe,nqptv,wtqp,np,x,y,z,dndxi,dndet,dndze);    element_volumes(iele) = elvolume;     cent = zeros(3,1);     for inpe =1:1:nnpe       inp1=np(iele,inpe);        cent(1) = cent(1)+sfac(inpe,1)*x(inp1);       cent(2) = cent(2)+sfac(inpe,1)*y(inp1);       cent(3) = cent(3)+sfac(inpe,1)*z(inp1);   end     element_centroids(:,iele) = cent(:);    bigNprime = BigNprimeMat(nnpe,nqptv,dndx,dndy,dndz);    se = ElementLaplacianMatrix(nnpe,nqptv,wtqp,bigNprime,detj,kmatrix);  me = ElementLHS4ConMass(nnpe,nqptv,wtqp,sfac,detj);  [Ksr,Ksc,Ksv,Jsr,Jsc,Jsv,Fsr,Fsv,fc,kc,jc] = AssembleSparseLaplace(iele,nnpe,np,se,me,fe,Ksr,Ksc,Ksv,Jsr,Jsc,Jsv,Fsr,Fsv,fc,kc,jc);end%% Define sparse matrices and clean up% f=sparse(Fsr,1,Fsv); sk=sparse(Ksr,Ksc,Ksv); mk=sparse(Jsr,Jsc,Jsv); sk = (sk+sk')/2; mk = (mk+mk')/2; clear Frr Fsv Ksr Ksc Ksv Jsr Jsc Jsv; if(eigsorsvds==1) % % options = optimoptions(@fmincon,'MaxIterations',1000,'MaxFunctionEvaluations',1000000,'Display','none');% options.MaxFunctionEvaluations = 1000000;% options.OptimalityTolerance = 1.0e-15;% options.StepTolerance  = 1.0e-15; [US,DS,VS,flag] = svds(sk,nummodes,'smallest','Tolerance',1e-18); elseif(eigsorsvds==0)  sigma = 1e-8;  [US,DS,flag] = eigs(sk,mk,nummodes,sigma,'Tolerance',1e-30);   end% message =  ['the convergence flag value is (0 means converged):'];% disp(message)% flaggrnstatus = 1;   clear sk mk;end if(eigsorsvds==1) USreverse = zeros(numnp,nummodes);for imodes = 1:1:nummodes      ireversenum = nummodes-imodes+1;        DS_Global(igrn,ireversenum) = DS(imodes,imodes);          DSreverse(ireversenum) = DS(imodes,imodes);     for inp = 1:1:numnp        itarget = meshfile1X.npcrossref(inp);        US_Global(itarget,ireversenum) = US(inp,imodes);        USreverse(inp,ireversenum) = US(inp,imodes);    endendmeshfile1X.grnstatus = grnstatus;meshfile1X.DS = DSreverse;meshfile1X.US = USreverse;elseif(eigsorsvds==0)meshfile1X.DS = DS;meshfile1X.US = US;for imodes = 1:1:nummodes        DS_Global(igrn,imodes) = DS(imodes,imodes);      for inp = 1:1:numnp        itarget = meshfile1X.npcrossref(inp);        US_Global(itarget,imodes) = US(inp,imodes);    endend endsave(grainmeshfilename,'meshfile1X');completed_grains(igrn)=1;status = ' Calculation of modes completed'         m_inverse  = zeros(3,3); grain_centroid = zeros(3,1); grain_weight = sum(element_volumes); grain_volumes(igrn) = grain_weight; element_weights = element_volumes/grain_weight;  %       compute grain centroid  for iele = 1:1:numel       grain_centroid(:) = grain_centroid(:) + element_weights(iele)*element_centroids(:,iele);    sample_volume = sample_volume+element_volumes(iele);  end        grain_centroids(:,igrn) = grain_centroid(:);           %       compute M_inverse for iele = 1:1:numel     element_centroid(:,iele) = element_centroids(:,iele)-grain_centroid(:); end      for iele = 1:1:numel     for j=1:1:3         for k=1:1:3            m_inverse(j,k) = m_inverse(j,k) + element_weights(iele)*(element_centroid(j,iele)*element_centroid(k,iele));         end     end end % perform SVD on m_sqrt     [MU,MS,MV] = svd(m_inverse); m_sqrt_U_Global(igrn,:,:) = MU(:,:);m_sqrt_S_Global(igrn,:,:) = MS(:,:);if(grnstatus==1)         for imodes = 1:1:nummodes        US_mode = zeros(numnp,1);    US_mode(:)=US(:,imodes);       grad_US_ele = zeros(3,numel,nqptv);        gradmaxs = zeros(3,1);    gradmins = zeros(3,1);    gradrangeqp = zeros(numel,1);    gradaverage = zeros(3,numel);for   iele =1:1:numel         [grad_u]=PostProcess_Laplace(iele,nnpe,np,x,y,z,nqptv,sfac,dndxi,dndet,dndze,US_mode);    for iqpt = 1:1:nqptv        grad_US_ele(:,iele,iqpt) = grad_u(:,iqpt);        gradaverage(:,iele) = gradaverage(:,iele)+grad_u(:,iqpt);    end    for icomp =1:1:3        gradmaxs(icomp) = max(grad_u(icomp,:));        gradmins(icomp) = min(grad_u(icomp,:));    end    gradrangeqp(iele) = max(gradmaxs(:)-gradmins(:));endmaxcomp = 1;% damping_factors = zeros(numel,1);dampflagel = zeros(numel,1);gradrangenp = zeros(numel,1);gradnpave = zeros(3,numnp);numelepernp = zeros(numnp,1);numfields = 3;feall = zeros(nnpe,numfields);% for   iele =1:1:numel            gradnp = zeros(3,nnpe);%           dampflag = 0;    damp_iter =0;% %  while (dampflag ==0)%         damp_iter = damp_iter+1;          igrain = grains(iele);    dampfac = damping_factors(iele);      [dndx,dndy,dndz,detj,elvolume] = SFDerivatives(iele,nnpe,nqptv,wtqp,np,x,y,z,dndxi,dndet,dndze);      bigN = sfac;    bigNprime = BigNprimeMat(nnpe,nqptv,dndx,dndy,dndz);      me = ElementLHS4ConPen(nnpe,nqptv,wtqp,bigN,bigNprime,detj,kmatrix,dampfac);        for ifield = 1:1:numfields%             switch ifield       case 1            data = grad_US_ele(1,iele,:);       case 2                                data = grad_US_ele(2,iele,:);       case 3                         data = grad_US_ele(3,iele,:);        end%                fe = ElementRHS4ConPen(nnpe,nqptv,wtqp,bigN,detj,data);            feall(:,ifield) = fe(:);%          end%         phi = me\feall;%         gradnp(1,:) = phi(:,1);            gradnp(2,:) = phi(:,2);    gradnp(3,:) = phi(:,3);% % %     gradelenp = zeros(nnpe,1);%     for jnp = 1:1:nnpe        gradelenp(jnp) = sqrt(phi(jnp,1)^2+phi(jnp,2)^2+phi(jnp,3)^2);    end%       gradmaxnp = max(gradelenp);    gradminnp = min(gradelenp);  gradrangenpmax = gradmaxnp-gradminnp;  gradrangenp(iele) = gradrangenpmax;%     if(gradrangenp(iele)  > 0.5*gradrangeqp(iele))      damping_factors(iele) = damp_iter*0.01;    else     dampflagel(iele) = 1;      dampflag = 1;   end%   if(damp_iter > 20)     dampflag = 1; end% % % end% for jnp = 1:1:nnpe    j1 = np(iele,jnp);    gradnpave(:,j1) = gradnpave(:,j1)+gradnp(:,jnp);    numelepernp(j1) = numelepernp(j1)+1;endend%     for inp = 1:1:numnp        gradnpave(:,inp) = gradnpave(:,inp)./numelepernp(inp);    end% % Put values in global array for current mode for current grain%     if(eigsorsvds==0)    for inp = 1:1:numnp        itarget = meshfile1X.npcrossref(inp);        itarget1 = 3*itarget-2;        itarget2 = 3*itarget-1;        itarget3 = 3*itarget;        grad_US_Global(itarget1,imodes) = gradnpave(1,inp);        grad_US_Global(itarget2,imodes) = gradnpave(2,inp);        grad_US_Global(itarget3,imodes) = gradnpave(3,inp);    end    else    for inp = 1:1:numnp        itarget = meshfile1X.npcrossref(inp);        itarget1 = 3*itarget-2;        itarget2 = 3*itarget-1;        itarget3 = 3*itarget;        grad_US_Global(itarget1,ireversenum) = gradnpave(1,inp);        grad_US_Global(itarget2,ireversenum) = gradnpave(2,inp);        grad_US_Global(itarget3,ireversenum) = gradnpave(3,inp);    end    endend    end    grain_weights = grain_volumes/sample_volume;        microstructurefile.grain_weights = grain_weights;    microstructurefile.grain_volumes = grain_volumes;    microstructurefile.sample_volume = sample_volume;     status = 'Calculation of mode gradients completed;  '     end    status = ' Finished mode and mode gradient computations for all grains;  '         status = ' Computing alignment of mode gradient and grain axes;  ' mode_grn_align_1= zeros(newnumnp,nummodes);mode_grn_align_2= zeros(newnumnp,nummodes);mode_grn_align_3= zeros(newnumnp,nummodes);MU = zeros(3,3);for inp = 1:1:newnumnp        inp3 = 3*inp;    inp2 = inp3-1;    inp1 = inp3-2;    gradvec = zeros(3,1);           grnnum = grn4np(inp);    MU(:,:) = m_sqrt_U_Global(grnnum,:,:);    grnvec1(:) = MU(:,1);    grnvec2(:) = MU(:,2);    grnvec3(:) = MU(:,3);        for imode = 1:1:nummodes        gradvec(1) = grad_US_Global(inp1,imode);        gradvec(2) = grad_US_Global(inp2,imode);        gradvec(3) = grad_US_Global(inp3,imode);        gradvec = gradvec/norm(gradvec);        mode_grn_align_1(inp,imode) = abs(grnvec1*gradvec);         mode_grn_align_2(inp,imode) = abs(grnvec2*gradvec);         mode_grn_align_3(inp,imode) = abs(grnvec3*gradvec);            end    end% Add results for all modes for all grainsharmonicmodefile    = Data_Structure_Harmonics(US_Global,DS_Global,grad_US_Global,completed_grains, ...    grain_centroids,m_sqrt_U_Global,m_sqrt_S_Global,mode_grn_align_1,mode_grn_align_2,mode_grn_align_3);mechmonicsvtkname = input('Base name of output VTK file: ', 's');save([mechmonicsvtkname '_modes.mat'],'harmonicmodefile');save([mechmonicsvtkname '_micro.mat'],'microstructurefile');SUF = 'vtk';file_harmonics_VTK = fopen(sprintf('%s.%s', [mechmonicsvtkname], SUF), 'w');Export_Harmonics_VTK(file_harmonics_VTK, harmonicmodefile , meshfilegbg,  phases,grains);status = 'Completed writing results to VTK file'clear all;